#!/usr/bin/env node
import {
  getGlobalConfigPath,
  getLocalConfigPath,
  unsetConfigValue
} from "./chunk-Y6NBWKEG.js";
import "./chunk-7XJYGZMH.js";
import "./chunk-MBLQFY4T.js";
import {
  findProjectRoot,
  requireProjectRoot
} from "./chunk-IWNALT6P.js";
import {
  ExitCode,
  reportError
} from "./chunk-IXNX2GX7.js";

// src/commands/config/unset.ts
import { defineCommand } from "citty";
import { log } from "@clack/prompts";
var unset_default = defineCommand({
  meta: { name: "unset", description: "Remove a configuration value" },
  args: {
    key: {
      type: "positional",
      required: true,
      description: "Config key in dot notation (e.g. ai.provider, database)"
    },
    global: {
      type: "boolean",
      description: "Remove from global config (~/.config/gram/config.yaml)",
      default: false
    }
  },
  async run({ args }) {
    const key = args.key;
    const projectRoot = args.global ? await findProjectRoot() : await requireProjectRoot();
    const configPath = args.global ? getGlobalConfigPath() : getLocalConfigPath(projectRoot);
    try {
      const removed = await unsetConfigValue(key, configPath, projectRoot);
      if (removed) {
        log.success(`Removed "${key}".`);
      } else {
        log.warn(`Key "${key}" was not set.`);
        process.exit(ExitCode.Error);
      }
    } catch (err) {
      reportError(err);
      process.exit(ExitCode.Error);
    }
  }
});
export {
  unset_default as default
};
